#define NOMINMAX
#define TAO_INPUT_SCALE
#define TAO_CPU_AVX2
#include "tokenizer_file.hpp"
#include "greedy_resident_lifecycle.hpp"
#include <cstdio>
int main(int argc,char**argv){using namespace tao::dual;using Clock=std::chrono::steady_clock;auto seconds=[](auto a){return std::chrono::duration<double>(Clock::now()-a).count();};std::string hash;auto tok=tao::text::load_tokenizer("build/formal_tokenizer.bbp",hash);auto begin=Clock::now();GreedyPipelineGroupedModel model(read_compact_bundle(argc>1?argv[1]:"build/noffn_fresh/step_100/final.dsb",hash));printf("LOAD seconds=%.6f\n",seconds(begin));auto prompt=tok.encode("你好，请用一句话介绍自己。");GreedyResidentSession session(model);for(int i=0;i<3;i++){session.reset();session.reply(prompt);}double total=0,ttft=0,decode=0;size_t decoded=0;int empty=0;for(int i=0;i<20;i++){session.reset();begin=Clock::now();auto r=session.reply(prompt);total+=seconds(begin);ttft+=r.ttft;decode+=r.decode_seconds;if(r.ids.size()>1)decoded+=r.ids.size()-1;empty+=r.ids.empty();}printf("NORMAL trials=20 prompt_tokens=%zu mean_reply_ms=%.6f empty=%d\n",prompt.size(),total*1000/20,empty);printf("NORMAL_DETAIL mean_ttft_ms=%.6f decode_steps=%zu decode_seconds=%.6f tps=%.3f\n",ttft*1000/20,decoded,decode,decode>0?decoded/decode:0);auto state=model.initial();uint32_t next=258;for(int i=0;i<64;i++)next=model.greedy_step(next,state);for(int round=0;round<5;round++){state=model.initial();model.advance(256,state);model.advance(257,state);for(auto t:prompt)model.advance(t,state);model.advance(259,state);begin=Clock::now();next=model.greedy_step(258,state);double first=seconds(begin);begin=Clock::now();for(int i=0;i<512;i++)next=model.greedy_step(next,state);double elapsed=seconds(begin);printf("FORCED round=%d steps=512 seconds=%.6f tps=%.3f ms_per_step=%.6f first_prediction_ms=%.6f checksum=%u\n",round,elapsed,512/elapsed,elapsed*1000/512,first*1000,next);}return 0;}
